<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Teacher'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$session=filter_var($_POST['session_id']??null,FILTER_VALIDATE_INT);$entries=is_array($_POST['learners']??null)?$_POST['learners']:[];if(!$session||!$entries){$_SESSION['error']='Choose a session and record at least one learner.';header('Location: ../?page=activities');exit;}$allowed=['Present','Absent','Excused'];$pdo=db();$s=null;try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT id,activity_id,DATE(starts_at) AS session_date FROM activity_sessions WHERE id=:id AND status<>'Cancelled' AND DATE(starts_at)<=CURDATE() FOR UPDATE");$q->execute(['id'=>$session]);$s=$q->fetch();if(!$s)throw new DomainException('Only a session scheduled for today or earlier can have its attendance taken.');$member=$pdo->prepare("SELECT id FROM activity_memberships WHERE activity_id=:activity AND student_id=:student AND status='Active' AND joined_on<=:session_date AND (left_on IS NULL OR left_on>=:session_date) LIMIT 1");$save=$pdo->prepare('INSERT INTO activity_session_attendance(session_id,student_id,status,note,recorded_by) VALUES(:session,:student,:status,:note,:user) ON DUPLICATE KEY UPDATE status=VALUES(status),note=VALUES(note),recorded_by=VALUES(recorded_by),recorded_at=CURRENT_TIMESTAMP');$count=0;foreach($entries as $student=>$row){$student=filter_var((string)$student,FILTER_VALIDATE_INT);if(!$student||!is_array($row))throw new DomainException('A learner attendance row is invalid.');$status=(string)($row['status']??'');if($status==='')continue;if(!in_array($status,$allowed,true))throw new DomainException('Choose a valid activity attendance status.');$note=trim((string)($row['note']??''));if(strlen($note)>255)throw new DomainException('Attendance notes must be 255 characters or fewer.');$member->execute(['activity'=>$s['activity_id'],'student'=>$student,'session_date'=>$s['session_date']]);if(!$member->fetch())throw new DomainException('Only members enrolled on the session date can be marked.');$save->execute(['session'=>$session,'student'=>$student,'status'=>$status,'note'=>$note?:null,'user'=>$user['id']]);$count++;}if(!$count)throw new DomainException('Record a status for at least one activity member.');audit_log('activity.attendance_saved','activity_session_attendance',(int)$session,['attendee_count'=>$count]);$pdo->commit();$_SESSION['notice']='Activity attendance saved for '.$count.' learner(s).';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Activity attendance failed: '.$e->getMessage());$_SESSION['error']=$e instanceof DomainException?$e->getMessage():'Could not save activity attendance.';}header('Location: ../?page=activities&activity='.(int)($s['activity_id']??0).'&session='.(int)$session);exit;
